//#region src/utils/agent_flag.ts
const coerceAgentFlag = (value) => {
	if (value === void 0) return [];
	const list = Array.isArray(value) ? value : [value];
	if (list.length === 0) throw new Error("--agent needs a value. Pass one, or omit the flag entirely.");
	return list.map((item) => {
		if (typeof item !== "string" || item.trim() === "") throw new Error("--agent needs a value. Pass one, or omit the flag entirely.");
		return item;
	});
};
const agentArgv = (agents) => agents.flatMap((id) => ["--agent", id]);
